head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > showProcessMessage]<br/>프로세스 창(Process Message Layer)을 표시하여 사용자 조작을 차단합니다.",
    "validation" : [
        "프로세스 창(Process Message Layer)을 표시하여 사용자 조작을 차단해야 합니다.",
        "Submission, ajax, Excel download 등의 비동기 작업이 진행 중일 때 사용자에게 진행 상태를 알리는 용도로 사용되어야 합니다.",
        "processMsg(필수) 파라미터로 프로세스 창에 표시할 진행 상태 메시지를 설정할 수 있어야 합니다.",
        "processMsg(필수) 파라미터에 '$blank' 를 설정하면 메시지 창이 표시되지 않아야 합니다.",
        "프로세스 창이 표시된 동안 키보드 입력이 차단되어야 합니다.",
        "processMsg(필수) 파라미터가 유효하지 않으면(빈 문자열/undefined/null) 프로세스 창이 표시되지 않아야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 프로세스 창 DOM 상태 확인
scwin.checkProcessLayer = function (prefix) {
    var modalEl = document.getElementById("___processbar2");
    var innerEl = document.getElementById("___processbar2_i");
    var modalVisible = modalEl ? (window.getComputedStyle(modalEl).display !== "none") : false;
    var innerVisible = innerEl ? (window.getComputedStyle(innerEl).display !== "none") : false;
    wf_body_bottom.getObj("scwin").setReturnValue(prefix + " ___processbar2 존재 : " + (modalEl ? "있음" : "없음") + ", 표시 : " + modalVisible);
    wf_body_bottom.getObj("scwin").setReturnValue(prefix + " ___processbar2_i 존재 : " + (innerEl ? "있음" : "없음") + ", 표시 : " + innerVisible);
}



scwin.btn_showProcessMessage_onclick = function () {
    var scenario = par_scenario.getValue();
    var msg = par_processMsg.getValue();

    if (scenario === "1") {
        // 정상 호출 (par_processMsg 값 사용)
        $p.showProcessMessage(msg);
        wf_body_bottom.getObj("scwin").setReturnValue("showProcessMessage('" + msg + "') 실행 (정상)");
    } else if (scenario === "2") {
        // 비동기 작업 시나리오 (2초 후 자동 hide)
        $p.showProcessMessage("비동기 작업 처리 중입니다...");
        wf_body_bottom.getObj("scwin").setReturnValue("showProcessMessage('비동기 작업 처리 중입니다...') 실행 (비동기 작업 시작)");
        setTimeout(function () {
            $p.hideProcessMessage();
            wf_body_bottom.getObj("scwin").setReturnValue("비동기 작업 완료 → hideProcessMessage 실행");
            scwin.checkProcessLayer("[비동기 작업 완료 후]");
        }, 2000);
    } else if (scenario === "3") {
        // 키보드 입력 차단 확인
        $p.showProcessMessage("키보드 입력 차단 테스트 중...");
        wf_body_bottom.getObj("scwin").setReturnValue("showProcessMessage('키보드 입력 차단 테스트 중...') 실행");
        setTimeout(function () {
            var dispatched = false, blocked = false;
            var testHandler = function (e) {
                dispatched = true;
                if (e.defaultPrevented || e.cancelBubble) blocked = true;
            };
            document.addEventListener("keydown", testHandler, false);
            var evt;
            try {
                evt = new KeyboardEvent("keydown", { key : "a", code : "KeyA", bubbles : true, cancelable : true });
            } catch (ex) {
                evt = document.createEvent("Event");
                evt.initEvent("keydown", true, true);
            }
            document.documentElement.dispatchEvent(evt);
            wf_body_bottom.getObj("scwin").setReturnValue("keydown 이벤트 발생 : " + dispatched + ", 차단(defaultPrevented/cancelBubble) : " + blocked);
            document.removeEventListener("keydown", testHandler, false);

            var inputEl = document.querySelector("input[id*='target_input1']");
            if (inputEl) {
                inputEl.focus();
                var activeId = document.activeElement ? document.activeElement.id : "";
                wf_body_bottom.getObj("scwin").setReturnValue("프로세스 창 표시 상태에서 target_input1 focus 시도 후 activeElement : " + activeId);
            }
            scwin.checkProcessLayer("[키보드 차단 테스트]");
        }, 500);
    } else if (scenario === "4") {
        // $blank → 미표시
        scwin.checkProcessLayer("[$blank 호출 전]");
        $p.showProcessMessage("$blank");
        wf_body_bottom.getObj("scwin").setReturnValue("showProcessMessage('$blank') 실행");
    } else if (scenario === "5") {
        // 빈 문자열 → 미표시
        scwin.checkProcessLayer("[빈 문자열 호출 전]");
        $p.showProcessMessage("");
        wf_body_bottom.getObj("scwin").setReturnValue("showProcessMessage('') 실행");
    } else if (scenario === "6") {
        // undefined → 미표시
        scwin.checkProcessLayer("[undefined 호출 전]");
        $p.showProcessMessage(undefined);
        wf_body_bottom.getObj("scwin").setReturnValue("showProcessMessage(undefined) 실행");
    } else if (scenario === "7") {
        // null → 미표시
        scwin.checkProcessLayer("[null 호출 전]");
        $p.showProcessMessage(null);
        wf_body_bottom.getObj("scwin").setReturnValue("showProcessMessage(null) 실행");
    }

    setTimeout(function () {
        scwin.checkProcessLayer("[showProcessMessage 후]");
    }, 300);
}



scwin.btn_hideProcessMessage_onclick = function () {
    $p.hideProcessMessage();
    wf_body_bottom.getObj("scwin").setReturnValue("hideProcessMessage 실행");
    setTimeout(function () {
        scwin.checkProcessLayer("[hideProcessMessage 후]");
    }, 300);
}
